-- UPGRADED CYBERTUBE IoT CYBERSECURITY COURSE DATABASE MIGRATION
-- 30 Modules • 120 Lessons • 120 Unique Verified YouTube Videos • 0 Duplicates • Zero Quizzes
-- Safe idempotent upsert: Preserves existing user progress and other courses.
BEGIN;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.courses WHERE slug='iot-cybersecurity-zero-to-advanced' AND id <> 'e1000000-0000-4000-8000-000000000001'::uuid) THEN RAISE EXCEPTION 'Course slug already claimed by another UUID'; END IF; END $$;

