INSERT INTO public.lessons (id, module_id, course_id, slug, title, description, youtube_video_id, duration_minutes, order_index, objectives, tags, skills_taught) VALUES (
  'e1000000-0101-4000-8000-000000000001'::uuid, 'e1000000-0001-4000-8000-000000000001'::uuid, 'e1000000-0000-4000-8000-000000000001'::uuid, 'm01-l01-how-an-iot-system-differs-from-conventional-it', 'Module 01 - Lesson 1: How an IoT system differs from conventional IT', 'Watch the assigned IoT-specific video(s), inspect a supplied diagram, sample log, firmware image or fictional design, and explain how **how an iot system differs from conventional it** affects confidentiality, integrity, availability, safety or privacy. Practice: Create a clearly labeled artifact for this subtopic (annotation, observation, rule hypothesis, comparison, or screenshot). State at least one attacker opportunity, one defense, and one verifiable indicator.', 'jY51TKyOq7U', 1, 1,
  ARRAY['Master How an IoT system differs from conventional IT', 'Apply: Create a clearly labeled artifact for this subtopic (annotation, observation, rule hypothesis, comparison, or screenshot). State at least one attacker opportunity, one defense, and one verifiable indicator.', 'Safe 3.3V DC limits']::text[],
