-- 4. VERIFY INTEGRITY (Exactly 30 modules, 120 lessons, 120 distinct video IDs)
DO $$
DECLARE
  v_module_count int;
  v_lesson_count int;
  v_unique_video_count int;
BEGIN
  SELECT count(*) INTO v_module_count FROM public.course_modules WHERE course_id = 'e1000000-0000-4000-8000-000000000001'::uuid;
  IF v_module_count <> 30 THEN
    RAISE EXCEPTION 'IoT course module count mismatch: expected 30, got %', v_module_count;
  END IF;

  SELECT count(*) INTO v_lesson_count FROM public.lessons WHERE course_id = 'e1000000-0000-4000-8000-000000000001'::uuid;
  IF v_lesson_count <> 120 THEN
    RAISE EXCEPTION 'IoT course lesson count mismatch: expected 120, got %', v_lesson_count;
  END IF;

  SELECT count(DISTINCT youtube_video_id) INTO v_unique_video_count FROM public.lessons WHERE course_id = 'e1000000-0000-4000-8000-000000000001'::uuid;
  IF v_unique_video_count <> 120 THEN
    RAISE EXCEPTION 'IoT course unique video count mismatch: expected 120, got %', v_unique_video_count;
  END IF;
END $$;

COMMIT;
